CREATE proc [dbo].[DailyFoodCostReportDateWise] @DateFrom as datetime, @DateTo as datetime as Select @DateFrom as datefrom,@DateTo as dateto,od.Date,i.Category_name,i.Id as ProductId,i.Item_Name as Product, isnull(sum(price),0)as TotalSale, Cast(isnull('0',0) AS DECIMAL (18,2)) as TotalCost , sum(od.qty) as TotalSaleQty, '' as UserId , (select department from CategoryPos where category_name = i.Category_name) as Department from Order_Detail od  inner join ItemPOS i on i.item_name=od.item_name  inner join dine_in_order d on d.order_key = od.order_key   WHERE OD.DATE BETWEEN @DateFrom AND @DateTo and d.Service_status = 'Close' group by od.Date,i.Category_name,i.Item_Name, i.sale_price,i.Id 